 "Description": "AWS CloudFormation Sample Template Route53_CNAME: Sample template showing how to create an Amazon Route 53 CNAME record.  It assumes that you already  have a Hosted Zone registered with Amazon Route 53. **WARNING** This template creates an Amazon EC2 instance. You will be billed for the AWS resources used if you create a stack from this template.",
 "Outputs": {
  "DomainName": {
   "Value": {
    "Ref": "myDNSRecord"
   }
  }
 },
 "Parameters": {
  "HostedZone": {
   "Description": "The DNS name of an existing Amazon Route 53 hosted zone",
   "Type": "String"
  }
 },
 "Resources": {
  "myDNSRecord": {
   "Properties": {
    "Comment": "CNAME redirect to aws.amazon.com.",
    "HostedZoneName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "HostedZone"
       },
       "."
      ]
     ]
    },
    "Name": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "AWS::StackName"
       },
       ".",
       {
        "Ref": "AWS::Region"
       },
       ".",
       {
        "Ref": "HostedZone"
       },
       "."
      ]
     ]
    },
    "ResourceRecords": [
     "aws.amazon.com"
    ],
    "TTL": "900",
    "Type": "CNAME"
   },
   "Type": "AWS::Route53::RecordSet"
  }
 }
}
]

tests/test_examples.py::test_example[examples/Route53_RoundRobin.py-{
 "Description": "AWS CloudFormation Sample Template Route53_RoundRobin: Sample template showing how to use weighted round robin (WRR) DNS entried via Amazon Route 53. This contrived sample uses weighted CNAME records to illustrate that the weighting influences the return records. It assumes  that you already have a Hosted Zone registered with Amazon Route 53. **WARNING** This template creates an Amazon EC2 instance. You will be billed for the AWS resources used if you create a stack from this template.",
 "Parameters": {
  "HostedZone": {
   "Description": "The DNS name of an existing Amazon Route 53 hosted zone",
   "Type": "String"
  }
 },
 "Resources": {
  "myDNSRecord": {
   "Properties": {
    "Comment": "Contrived example to redirect to aws.amazon.com 75% of the time and www.amazon.com 25% of the time.",
    "HostedZoneName": {
     "Fn::Join": [
      "",
      [
       {
        "Ref": "HostedZone"
       },
       "."
      ]
     ]
    },
    "RecordSets": [
     {
      "Name": {
       "Fn::Join": [
        "",
        [
         {
          "Ref": "AWS::StackName"
         },
         ".",
         {
          "Ref": "AWS::Region"
         },
         ".",
         {
          "Ref": "HostedZone"
         },
         "."
        ]
       ]
      },
      "ResourceRecords": [
       "aws.amazon.com"
      ],
      "SetIdentifier": {
       "Fn::Join": [
        " ",
        [
         {
          "Ref": "AWS::StackName"
         },
         "AWS"
        ]
       ]
      },
      "TTL": "900",
      "Type": "CNAME",
      "Weight": "3"
     },
     {
      "Name": {
       "Fn::Join": [
        "",
        [
         {
          "Ref": "AWS::StackName"
         },
         ".",
         {
          "Ref": "AWS::Region"
         },
         ".",
         {
          "Ref": "HostedZone"
         },
         "."
        ]
       ]
      },
      "ResourceRecords": [
       "www.amazon.com"
      ],
      "SetIdentifier": {
       "Fn::Join": [
        " ",
        [
         {
          "Ref": "AWS::StackName"
         },
         "Amazon"
        ]
       ]
      },
      "TTL": "900",
      "Type": "CNAME",
      "Weight": "1"
     }
    ]
   },
   "Type": "AWS::Route53::RecordSetGroup"
  }
 }
}
]

