tests/test_examples.py::test_example[examples/EMR_Cluster.py-{
 "Conditions": {
  "WithSpotPrice": {
   "Fn::Not": [
    {
     "Fn::Equals": [
      {
       "Ref": "SpotPrice"
      },
      "0"
     ]
    }
   ]
  }
 },
 "Description": "Sample CloudFormation template for creating an EMR cluster",
 "Parameters": {
  "GcTimeRatioValue": {
   "Default": "19",
   "Description": "Hadoop name node garbage collector time ratio",
   "Type": "Number"
  },
  "KeyName": {
   "Description": "Name of an existing EC2 KeyPair to enable SSH to the instances",
   "Type": "AWS::EC2::KeyPair::KeyName"
  },
  "SpotPrice": {
   "Default": "0.1",
   "Description": "Spot price (or use 0 for 'on demand' instance)",
   "Type": "Number"
  },
  "Subnet": {
   "Description": "Subnet ID for creating the EMR cluster",
   "Type": "AWS::EC2::Subnet::Id"
  }
 },
 "Resources": {
  "EMRInstanceProfile": {
   "Properties": {
    "Roles": [
     {
      "Ref": "EMRJobFlowRole"
     }
    ]
   },
   "Type": "AWS::IAM::InstanceProfile"
  },
  "EMRJobFlowRole": {
   "Properties": {
    "AssumeRolePolicyDocument": {
     "Statement": [
      {
       "Action": [
        "sts:AssumeRole"
       ],
       "Effect": "Allow",
       "Principal": {
        "Service": [
         "ec2.amazonaws.com"
        ]
       }
      }
     ]
    },
    "ManagedPolicyArns": [
     "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforEC2Role"
    ]
   },
   "Type": "AWS::IAM::Role"
  },
  "EMRSampleCluster": {
   "Properties": {
    "Applications": [
     {
      "Name": "Hadoop"
     },
     {
      "Name": "Hive"
     },
     {
      "Name": "Mahout"
     },
     {
      "Name": "Pig"
     },
     {
      "Name": "Spark"
     }
    ],
    "AutoScalingRole": "EMR_AutoScaling_DefaultRole",
    "BootstrapActions": [
     {
      "Name": "Dummy bootstrap action",
      "ScriptBootstrapAction": {
       "Args": [
        "dummy",
        "parameter"
       ],
       "Path": "file:/usr/share/aws/emr/scripts/install-hue"
      }
     }
    ],
    "Configurations": [
     {
      "Classification": "core-site",
      "ConfigurationProperties": {
       "hadoop.security.groups.cache.secs": "250"
      }
     },
     {
      "Classification": "mapred-site",
      "ConfigurationProperties": {
       "mapred.tasktracker.map.tasks.maximum": "2",
       "mapreduce.map.sort.spill.percent": "90",
       "mapreduce.tasktracker.reduce.tasks.maximum": "5"
      }
     },
     {
      "Classification": "hadoop-env",
      "Configurations": [
       {
        "Classification": "export",
        "ConfigurationProperties": {
         "HADOOP_DATANODE_HEAPSIZE": "2048",
         "HADOOP_NAMENODE_OPTS": {
          "Fn::Join": [
           "",
           [
            "-XX:GCTimeRatio=",
            {
             "Ref": "GcTimeRatioValue"
            }
           ]
          ]
         }
        }
       }
      ]
     }
    ],
    "Instances": {
     "CoreInstanceGroup": {
      "AutoScalingPolicy": {
       "Constraints": {
        "MaxCapacity": "3",
        "MinCapacity": "1"
       },
       "Rules": [
        {
         "Action": {
          "Market": "ON_DEMAND",
          "SimpleScalingPolicyConfiguration": {
           "AdjustmentType": "EXACT_CAPACITY",
           "CoolDown": "300",
           "ScalingAdjustment": "1"
          }
         },
         "Description": "CoreAutoScalingPolicy rules",
         "Name": "CoreAutoScalingPolicy",
         "Trigger": {
          "CloudWatchAlarmDefinition": {
           "ComparisonOperator": "GREATER_THAN",
           "Dimensions": [
            {
             "Key": "my.custom.master.property",
             "Value": "my.custom.master.value"
            }
           ],
           "EvaluationPeriods": "120",
           "MetricName": "TestMetric",
           "Namespace": "AWS/ElasticMapReduce",
           "Period": "300",
           "Statistic": "AVERAGE",
           "Threshold": "50",
           "Unit": "PERCENT"
          }
         }
        }
       ]
      },
      "BidPrice": {
       "Fn::If": [
        "WithSpotPrice",
        {
         "Ref": "SpotPrice"
        },
        {
         "Ref": "AWS::NoValue"
        }
       ]
      },
      "EbsConfiguration": {
       "EbsBlockDeviceConfigs": [
        {
         "VolumeSpecification": {
          "SizeInGB": "10",
          "VolumeType": "gp2"
         },
         "VolumesPerInstance": "1"
        }
       ],
       "EbsOptimized": true
      },
      "InstanceCount": "1",
      "InstanceType": "m4.large",
      "Market": {
       "Fn::If": [
        "WithSpotPrice",
        "SPOT",
        "ON_DEMAND"
       ]
      },
      "Name": "Core Instance"
     },
     "Ec2KeyName": {
      "Ref": "KeyName"
     },
     "Ec2SubnetId": {
      "Ref": "Subnet"
     },
     "MasterInstanceGroup": {
      "AutoScalingPolicy": {
       "Constraints": {
        "MaxCapacity": "3",
        "MinCapacity": "1"
       },
       "Rules": [
        {
         "Action": {
          "Market": "ON_DEMAND",
          "SimpleScalingPolicyConfiguration": {
           "AdjustmentType": "EXACT_CAPACITY",
           "CoolDown": "300",
           "ScalingAdjustment": "1"
          }
         },
         "Description": "MasterAutoScalingPolicy rules",
         "Name": "MasterAutoScalingPolicy",
