    ],
    "UserData": {
     "Fn::Base64": {
      "Fn::Join": [
       "",
       [
        "#!/bin/bash -xe\n",
        "yum update -y aws-cfn-bootstrap\n",
        "# Setup the PHP sample application\n",
        "/opt/aws/bin/cfn-init -v ",
        "         --stack ",
        {
         "Ref": "AWS::StackName"
        },
        "         --resource WebServerInstance ",
        "         --region ",
        {
         "Ref": "AWS::Region"
