        "\n",
        "# Signal the status of cfn-init\n",
        "/opt/aws/bin/cfn-signal -e $? ",
        "         --stack ",
        {
         "Ref": "AWS::StackName"
        },
        "         --resource WebServerInstance ",
        "         --region ",
        {
         "Ref": "AWS::Region"
        },
        "\n"
       ]
      ]
     }
    }
   },
   "Type": "AWS::EC2::Instance"
  },
  "WebServerInstanceProfile": {
   "Properties": {
    "Path": "/",
