 "Conditions": {
  "OnDemand": {
   "Fn::Equals": [
    {
     "Ref": "BillOnDemand"
    },
    "true"
   ]
  }
 },
 "Description": "Create two dynamodb tables with conditional on-demand billing. One with global secondary index and one without",
 "Outputs": {
  "GSITable": {
   "Description": "Table with a Global Secondary Index",
   "Value": {
    "Ref": "GSITable"
   }
  }
 },
